/* Bench demos viewer beacon — generated by publish-demos-site.sh, do not edit.
   Tells the Bench who is on a demo and for how long; nothing else leaves the page. */
(function(URL,SRC,SLUG){
"use strict";
if(!URL)return;
var d=document,slug=SLUG||(location.pathname.split("/").filter(Boolean)[0]||"home").replace(/\.html$/,"");
var key="bench-sid:"+slug,sid="";
try{sid=sessionStorage.getItem(key)||"";}catch(e){}
if(!/^[a-z0-9]{16}$/.test(sid)){
  sid="";for(var i=0;i<16;i++)sid+=Math.floor(Math.random()*36).toString(36);
  try{sessionStorage.setItem(key,sid);}catch(e){}
}
function locked(){return /\bbench-locked\b/.test(d.documentElement.className);}
function ping(){
  if(locked())return;
  var b=JSON.stringify({sid:sid,slug:slug,source:SRC});
  try{if(navigator.sendBeacon&&navigator.sendBeacon(URL,b))return;}catch(e){}
  try{fetch(URL,{method:"POST",body:b,mode:"no-cors",keepalive:true,headers:{"Content-Type":"text/plain"}})["catch"](function(){});}catch(e){}
}
if(locked()){var w=setInterval(function(){if(!locked()){clearInterval(w);ping();}},1000);}else ping();
setInterval(function(){if(!d.hidden)ping();},20000);
d.addEventListener("visibilitychange",ping);
addEventListener("pagehide",ping);
})("https://bench.tail81b22c.ts.net:8443/api/beacon","netlify","");
